import numpy as np

v = np.array([1, 2])
for w in ([3, 1], [-2, 1], [-1, -2]):
    print(w, np.dot(v, w))      # 5, 0, -5

# 장난감 '여럿 방향' 실험: [동물다움, 여럿임]
E = {'cat': np.array([2.0, 0.1]), 'cats': np.array([2.0, 1.1]),
     'dog': np.array([1.9, 0.0]), 'dogs': np.array([1.9, 1.0])}
plur = E['cats'] - E['cat']
for word in ('dog', 'dogs'):
    print(word, round(float(plur @ E[word]), 2))   # dogs 가 더 크다
